 164	\begin{lemma}\label{lem:alnf}
 165		\lean{MIPStarRE.QPBT.aLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.aLinePointDist_mem_line}
 166		\leanok
 167		\uses{def:line-point-dist, def:line}
 168		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
 169	\end{lemma}
 170	\begin{proof}
 171		\leanok
 172		\uses{def:cl-dist, def:ld-question-distribution, def:ld-line-description, def:line-representative, lem:distribution-map-comp, lem:uniform-map-equivalence, lem:uniform-product-first-marginal, lem:uniform-product-second-marginal, lem:chi-index-uniform, lem:line-representative-idempotent, lem:line-rep-incidence}
 173		By Definition~\ref{def:cl-dist} the distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$ is the push-forward of the uniform distribution on $V$ along $z \mapsto \bigl(L_{\mathsf{ALine}}(z), L_{\mathsf{Point}}(z)\bigr)$, so each marginal below is the push-forward of the uniform distribution on $V$ along the composite of that map with the corresponding coordinate. The point marginal is the image of the uniform distribution on $V$ under $(u,s,v) \mapsto u$, hence uniform on $\F_q^m$. The axis marginal is its image under $(u,s,v) \mapsto \chi(s)$; since $m$ divides $q$, every fibre of $\chi$ has exactly $q/m$ elements, so $i = \chi(s)$ is uniform on $\{1,2,\ldots,m\}$ and $(u_0,s)$ specifies a uniformly random axis-parallel line $\ell(u_0,e_i)$. Finally the base point recorded in the sample is $u_0 = L^{\mathrm{Ln}}_{e_i}(u)$, which is fixed by $L^{\mathrm{Ln}}_{e_i}$ (Definition~\ref{def:line-representative}) and satisfies $u \in \ell(u_0,e_i)$ by Lemma~\ref{lem:line-rep-incidence}.
 174	\end{proof}
